<?php
declare(strict_types=1); namespace Theobroma\OneC\Import;
final class CatalogUpdateService {public function __construct(private readonly ProductMatcher$matcher){}public static function wordpress():self{return new self(new ProductMatcher(function(string$field,string$value):array{if($field==='woo_sku'){$id=(int)wc_get_product_id_by_sku($value);return$id>0?[$id]:[];}$meta=['1c_guid'=>'_theobroma_1c_guid','1c_article'=>'_theobroma_1c_article','client_article'=>'_theobroma_client_article','ozon_product_id'=>'_theobroma_ozon_product_id','ozon_sku'=>'_theobroma_ozon_sku','ean'=>'_theobroma_ean'][$field];$ids=array_map('intval',get_posts(['post_type'=>['product','product_variation'],'post_status'=>'any','fields'=>'ids','numberposts'=>2,'meta_key'=>$meta,'meta_value'=>$value]));if($field==='1c_article'){$sku=(int)wc_get_product_id_by_sku($value);if($sku>0)$ids[]=$sku;}return array_values(array_unique($ids));}));}/** @param list<CatalogUpdate> $updates */public function apply(array$updates,bool$stock,bool$prices):ImportResult{$a=$s=$amb=$err=0;foreach($updates as$u){$m=$this->matcher->match($u->identifiers);if($m->status==='ambiguous'){$amb++;continue;}if(!$m->productId){$s++;continue;}$p=wc_get_product($m->productId);if(!$p instanceof \WC_Product){$s++;continue;}try{$changed=false;if($stock&&$u->stock!==null){$p->set_manage_stock(true);$p->set_stock_quantity($u->stock);$p->set_stock_status($u->stock>0?'instock':'outofstock');$changed=true;}if($prices&&$u->price!==null){$p->set_regular_price($u->price);if((string)$p->get_sale_price()==='')$p->set_price($u->price);$changed=true;}if($changed){$p->save();$a++;}else$s++;}catch(\Throwable){$err++;}}return new ImportResult($a,$s,$amb,$err);}}
